3	     3	/// Switch by Speaker's planner (road map "creator-jobs" SW2a, spec §11
4	     4	/// SW-20…SW-25): which microphone is active on a 10 ms grid, the shots those
5	     5	/// turns make on the angle tracks, and every refusal named at once. Nothing
6	     6	/// here is visible yet; SW2b's sheet and tool write the shots onto a Program
7	     7	/// track.
8	     8	///
9	     9	/// Pure (SW-25): `defaults`, `plan`, `labels` and `shots` read no document,
10	    10	/// file or clock. `read` (`SpeakerSwitch+Read.swift`) is the one reader, and
11	    11	/// the series it builds are `ClipLevelSeries`'. Names no `rc_*` but
12	    12	/// `ReelTime.snapToFrame` and `ReelTime.format`.
13	    13	enum SpeakerSwitch {
14	    14	    static let actionName = "Switch by Speaker"
15	    15	    static let maxAngles = 9
16	    16	
17	    17	    /// What a qualifying crosstalk turn does: show the wide, or hold.
18	    18	    enum Crosstalk: String { case wide, hold }
19	    19	
20	    20	    /// Seconds and dB; the defaults are SW-S4's (SW-21) and SW-22's drafts.
21	    21	    struct Settings: Equatable {
22	    22	        var minShot = 2.0, minTurn = 1.0, lead = 0.2, crosstalkMin = 1.0, bridge = 0.5
23	    23	        var crosstalk: Crosstalk = .wide
24	    24	        var bleedDB = 15.0, dominanceDB = 8.0, floorMarginDB = 6.0, voiceThreshold: Float = 0.5
25	    25	        /// nil = off.
26	    26	        var wideAfter: Double? = nil
27	    27	        /// The faces mode's label (SW-81): the top angle's activity over the next's, and the
28	    28	        /// floor it must exceed.
29	    29	        var faceRatio = FaceActivity.ratio, faceFloor = FaceActivity.floor
30	    30	    }
31	    31	
32	    32	    /// Who says who is talking (SW-83): each microphone its own person, or one microphone shared
33	    33	    /// by two or more angles and their faces (`SpeakerSwitch+Faces.swift`).
34	    34	    enum Mode: String { case microphones, faces }
35	    35	
36	    36	    /// One face-speaker angle's mouth activity on the range's grid (SW-81): step k's activity,
37	    37	    /// nil where none can be read. Empty: not read.
38	    38	    struct FaceAngle: Equatable {
39	    39	        let track: UInt32
40	    40	        let activity: [Double?]
41	    41	    }
42	    42	
43	    43	    /// A person: their microphone track and the angle track that shows them.
44	    44	    struct Speaker: Equatable { let mic: UInt32?; let angle: UInt32? }
45	    45	    struct Pairing: Equatable { let speakers: [Speaker]; let wide: UInt32? }
46	    46	    struct Span: Equatable { let clip: UInt32; let start: Ticks; let end: Ticks }
47	    47	    /// An angle track and its picture clips (`SwitchAngle.pictureClips`), by start.
48	    48	    struct AngleTrack: Equatable { let track: UInt32; let clips: [Span] }
49	    49	
50	    50	    /// One microphone track on the range's grid: step k is
51	    51	    /// `[from + k·step, from + (k+1)·step)`. Empty arrays: not read.
52	    52	    struct Microphone: Equatable {
53	    53	        let track: UInt32
54	    54	        /// ℓ(k) in dB over the centred window; −∞ when silent.
55	    55	        let level: [Double]
56	    56	        /// v(k).
57	    57	        let voice: [Float]
58	    58	        /// A selected clip of this track plays at the step's midpoint.
59	    59	        let covered: [Bool]
60	    60	    }
61	    61	
62	    62	    struct Input {
63	    63	        let from: Ticks, to: Ticks, fps: Fps
64	    64	        /// Front first.
65	    65	        let angles: [AngleTrack]
66	    66	        /// Front first.
67	    67	        let microphones: [Microphone]
68	    68	        let pairing: Pairing
69	    69	        /// `read`'s: still analysed, no speech detection.
70	    70	        let problems: [String]
71	    71	        /// `ShotSplit.clipCount` of the document's project.
72	    72	        let clipCount: Int
73	    73	        let settings: Settings
74	    74	        /// The faces mode's angles, front first (`readFaces`); empty in the microphones mode.
75	    75	        var faces: [FaceAngle] = []
76	    76	    }
77	    77	
78	    78	    /// A step's label; `person` names the microphone track (in the faces mode, the angle's).
79	    79	    enum Label: Equatable { case person(UInt32), crosstalk, nobody }
80	    80	    struct Shot: Equatable { let angle: UInt32; let start: Ticks; let end: Ticks }
81	    81	    enum Plan: Equatable { case refused([String]); case planned(shots: [Shot], added: Int) }
82	    82	
83	    83	    // MARK: - SW-20's defaults
84	    84	
85	    85	    /// The angles, microphones and pairing a selection implies, front first.
86	    86	    static func defaults(selection: [ClipSnapshot], in snapshot: ProjectSnapshot)
87	    87	        -> (angles: [UInt32], microphones: [UInt32], pairing: Pairing)
88	    88	    {
89	    89	        let front = snapshot.tracks.reversed().map(\.id)
90	    90	        func holds(_ track: UInt32, _ test: (ClipSnapshot) -> Bool) -> Bool {
91	    91	            selection.contains { $0.track == track && test($0) }
92	    92	        }
93	    93	        let angles = front.filter { holds($0) { isPicture($0, in: snapshot) } }
94	    94	        let files = front.filter {
95	    95	            holds($0) { playsSound($0, in: snapshot) && snapshot.media(for: $0)?.hasVideo == false }
96	    96	        }
97	    97	        let microphones = files.isEmpty
98	    98	            ? angles.filter { holds($0) { playsSound($0, in: snapshot) } } : files
99	    99	
100	   100	        var speakers: [Speaker] = []
101	   101	        var used: Set<UInt32> = []
102	   102	        for mic in microphones where angles.contains(mic) {
103	   103	            used.insert(mic)
104	   104	        }
105	   105	        var free = angles.filter { !used.contains($0) }.makeIterator()
106	   106	        for mic in microphones {
107	   107	            if angles.contains(mic) {
108	   108	                speakers.append(Speaker(mic: mic, angle: mic))
109	   109	            } else if let angle = free.next() {
110	   110	                used.insert(angle)
111	   111	                speakers.append(Speaker(mic: mic, angle: angle))
112	   112	            } else {
113	   113	                speakers.append(Speaker(mic: mic, angle: nil))
114	   114	            }
115	   115	        }
116	   116	        let left = angles.filter { !used.contains($0) }
117	   117	        // SW-83: one microphone shared by every angle, and no wide (the faces mode).
118	   118	        if microphones.count == 1, angles.count >= 2, let mic = microphones.first {
119	   119	            return (angles, microphones,
120	   120	                    Pairing(speakers: angles.map { Speaker(mic: mic, angle: $0) }, wide: nil))
121	   121	        }
122	   122	        return (angles, microphones,
123	   123	                Pairing(speakers: speakers, wide: left.count == 1 ? left.first : nil))
124	   124	    }
125	   125	
126	   126	    /// A `detach_audio` half: the sound of a file with pictures.
127	   127	    static func isDetachedSound(_ clip: ClipSnapshot, in snapshot: ProjectSnapshot) -> Bool {
128	   128	        !clip.enabled.video && clip.linked != nil && snapshot.media(for: clip)?.hasVideo == true
129	   129	    }
130	   130	
131	   131	    /// A media clip with a picture that may make its track an angle.
132	   132	    static func isPicture(_ clip: ClipSnapshot, in snapshot: ProjectSnapshot) -> Bool {
133	   133	        guard case .media = clip.source, snapshot.sourceSize(of: clip) != nil else { return false }
134	   134	        return !(clip.enabled.video == false && clip.linked != nil)
135	   135	    }
136	   136	
137	   137	    /// A media clip that sounds, by the snapshot alone (no plan here): its
138	   138	    /// media has audio, its sound is on, and it is no detached camera sound.
139	   139	    static func playsSound(_ clip: ClipSnapshot, in snapshot: ProjectSnapshot) -> Bool {
140	   140	        guard case .media = clip.source, clip.enabled.audio,
141	   141	            snapshot.media(for: clip)?.hasAudio == true
142	   142	        else { return false }
143	   143	        return !isDetachedSound(clip, in: snapshot)
144	   144	    }
