146	   146	    // MARK: - The plan
147	   147	
148	   148	    static func plan(_ input: Input) -> Plan {
149	   149	        let refusals = refusals(input)
150	   150	        if !refusals.isEmpty { return .refused(refusals) }
151	   151	        let step = stepTicks
152	   152	        let count = step > 0 ? Int(max(0, input.to - input.from) / step) : 0
153	   153	        let faces = mode(input.pairing) == .faces
154	   154	        let all = faces
155	   155	            ? faceLabels(input)
156	   156	            : labels(input.microphones.filter { $0.level.count == count }, settings: input.settings)
157	   157	        let planned = shots(
158	   158	            labels: all, from: input.from, to: input.to, fps: input.fps,
159	   159	            pairing: faces ? facePairing(input.pairing) : input.pairing,
160	   160	            angles: input.angles, settings: input.settings)
161	   161	        let added = clipsAdded(planned, angles: input.angles, from: input.from, to: input.to)
162	   162	        let most = Int(RC_MAX_CLIPS)
163	   163	        if input.clipCount + added > most {
164	   164	            return .refused([
165	   165	                "Switch by Speaker would add \(added) clips to \(input.clipCount); the most is "
166	   166	                    + "\(most) — raise the minimum shot."
167	   167	            ])
168	   168	        }
169	   169	        return .planned(shots: planned, added: added)
170	   170	    }
171	   171	
172	   172	    /// SW-24's list, in its order; empty when nothing is refused.
173	   173	    static func refusals(_ input: Input) -> [String] {
174	   174	        var out: [String] = []
175	   175	        let angles = input.angles.map(\.track)
176	   176	        if angles.count < 2 {
177	   177	            out.append(
178	   178	                "Switch by Speaker needs at least two angles: tracks holding a selected clip "
179	   179	                    + "with a picture.")
180	   180	        }
181	   181	        if angles.count > maxAngles {
182	   182	            out.append(
183	   183	                "Switch by Speaker takes at most nine angles; \(angles.count) tracks hold a "
184	   184	                    + "selected clip with a picture.")
185	   185	        }
186	   186	        let microphones = input.microphones.map(\.track)
187	   187	        let faces = mode(input.pairing) == .faces
188	   188	        // SW-83: in the faces mode a speaker on the wide takes no part.
189	   189	        for speaker in input.pairing.speakers
190	   190	        where !(faces && speaker.angle != nil && speaker.angle == input.pairing.wide) {
191	   191	            guard let mic = speaker.mic, microphones.contains(mic) else {
192	   192	                let track = speaker.angle ?? speaker.mic ?? 0
193	   193	                out.append("The speaker on track \(track) has no microphone.")
194	   194	                continue
195	   195	            }
196	   196	            if speaker.angle.map({ !angles.contains($0) }) ?? true {
197	   197	                out.append("The microphone on track \(mic) has no angle to show its speaker.")
198	   198	            }
199	   199	        }
200	   200	        var counted: [UInt32] = []
201	   201	        for mic in input.pairing.speakers.compactMap(\.mic) where !faces && !counted.contains(mic) {
202	   202	            counted.append(mic)
203	   203	            let n = input.pairing.speakers.filter { $0.mic == mic }.count
204	   204	            if n > 1 {
205	   205	                out.append(
206	   206	                    "Track \(mic) is the microphone for \(n) speakers; each person needs their "
207	   207	                        + "own microphone.")
208	   208	            }
209	   209	        }
210	   210	        out += input.problems
211	   211	        let count = stepTicks > 0 ? Int(max(0, input.to - input.from) / stepTicks) : 0
212	   212	        let a = ReelTime.format(input.from, fps: input.fps, frames: true)
213	   213	        let b = ReelTime.format(input.to, fps: input.fps, frames: true)
214	   214	        out += silentMicrophones(input)
215	   215	        // SW-84: a read angle with no step whose mouth can be read.
216	   216	        for angle in input.faces where angle.activity.count == count
217	   217	            && !angle.activity.contains(where: { $0 != nil })
218	   218	        {
219	   219	            out.append(
220	   220	                "The camera on track \(angle.track) shows no face whose mouth can be read between "
221	   221	                    + "\(a) and \(b), so it never says who is talking.")
222	   222	        }
223	   223	        if let gap = firstGap(input.angles, from: input.from, to: input.to) {
224	   224	            out.append(
225	   225	                "No angle has a picture between "
226	   226	                    + "\(ReelTime.format(gap.from, fps: input.fps, frames: true)) and "
227	   227	                    + "\(ReelTime.format(gap.to, fps: input.fps, frames: true)).")
228	   228	        }
229	   229	        return out
230	   230	    }
231	   231	
232	   232	    /// SW-24's no-speech sentences: each read microphone with no speech step inside the range.
233	   233	    static func silentMicrophones(_ input: Input) -> [String] {
234	   234	        var out: [String] = []
235	   235	        let count = stepTicks > 0 ? Int(max(0, input.to - input.from) / stepTicks) : 0
236	   236	        let a = ReelTime.format(input.from, fps: input.fps, frames: true)
237	   237	        let b = ReelTime.format(input.to, fps: input.fps, frames: true)
238	   238	        for mic in input.microphones where mic.voice.count == count {
239	   239	            let speaks = mic.voice.indices.contains {
240	   240	                mic.covered[$0] && mic.voice[$0] >= input.settings.voiceThreshold
241	   241	            }
242	   242	            if !speaks {
243	   243	                out.append(
244	   244	                    "The microphone on track \(mic.track) has no speech between \(a) and \(b), "
245	   245	                        + "so it never says who is talking.")
246	   246	            }
247	   247	        }
248	   248	        return out
249	   249	    }
250	   250	
251	   251	    /// The first stretch of `[from, to)` no angle covers.
252	   252	    static func firstGap(_ angles: [AngleTrack], from: Ticks, to: Ticks)
253	   253	        -> (from: Ticks, to: Ticks)?
254	   254	    {
255	   255	        var t = from
256	   256	        while t < to {
257	   257	            if let end = angles.compactMap({ reach($0, from: t) }).max() {
258	   258	                t = end
259	   259	                continue
260	   260	            }
261	   261	            let next = angles.flatMap(\.clips).map(\.start).filter { $0 > t }.min() ?? to
262	   262	            return (t, min(next, to))
263	   263	        }
264	   264	        return nil
265	   265	    }
266	   266	
267	   267	    /// How far `angle`'s clips cover contiguously from `t`; nil when they
268	   268	    /// do not cover `t` (SW-13's rule).
269	   269	    static func reach(_ angle: AngleTrack, from t: Ticks) -> Ticks? {
270	   270	        var reached = angle.clips.filter { $0.start <= t && $0.end > t }.map(\.end).max()
271	   271	        // A clip starting at or before the edge extends it (abutting files
272	   272	        // cover their join): loop until the edge no longer moves.
273	   273	        while let end = reached {
274	   274	            let further = angle.clips.filter { $0.start <= end && $0.end > end }.map(\.end).max()
275	   275	            guard let further else { break }
276	   276	            reached = further
277	   277	        }
278	   278	        return reached
279	   279	    }
280	   280	
281	   281	    /// SW-24's N: per shot, the angle clips it overlaps (the later one
282	   282	    /// taking over where two overlap, SW-15 (d)), plus a split for each
283	   283	    /// angle clip straddling `from` and each straddling `to`.
284	   284	    static func clipsAdded(_ shots: [Shot], angles: [AngleTrack], from: Ticks, to: Ticks) -> Int {
285	   285	        var n = 0
286	   286	        for shot in shots {
287	   287	            guard let angle = angles.first(where: { $0.track == shot.angle }) else { continue }
288	   288	            let crossing = angle.clips.filter { $0.end > shot.start && $0.start < shot.end }
289	   289	            for (index, clip) in crossing.enumerated() {
290	   290	                let next = index + 1 < crossing.count ? crossing[index + 1].start : shot.end
291	   291	                if min(clip.end, next, shot.end) > max(clip.start, shot.start) { n += 1 }
292	   292	            }
293	   293	        }
294	   294	        for clip in angles.flatMap(\.clips) {
295	   295	            if clip.start < from && from < clip.end { n += 1 }
296	   296	            if clip.start < to && to < clip.end { n += 1 }
297	   297	        }
298	   298	        return n
299	   299	    }
300	   300	}
