303	     3	/// Switch by Speaker's values, as both doors take them (spec §11 SW-26 (d)): the ranges the sheet
304	     4	/// clamps to and `switch_by_speaker` refuses outside of, the four values the sheet remembers, and
305	     5	/// the summary the sheet shows. Pure but for the `UserDefaults` it is handed; names no `rc_*`.
306	     6	extension SpeakerSwitch.Settings {
307	     7	    /// Seconds.
308	     8	    static let minShotRange: ClosedRange<Double> = 0.5...30
309	     9	    /// Seconds; the tool's alone (SW-26 (d)).
310	    10	    static let minTurnRange: ClosedRange<Double> = 0.2...10
311	    11	    /// Seconds.
312	    12	    static let leadRange: ClosedRange<Double> = 0...1
313	    13	    /// dB below a speaker's own level.
314	    14	    static let bleedRange: ClosedRange<Double> = 3...40
315	    15	    /// dB; the tool's alone (SW-26 (d)).
316	    16	    static let dominanceRange: ClosedRange<Double> = 0...30
317	    17	    /// Seconds.
318	    18	    static let wideAfterRange: ClosedRange<Double> = 2...600
319	    19	    /// The sheet's field when "Cut to the wide after" is first ticked (the owner: offered, off).
320	    20	    static let wideAfterOffered = 20.0
321	    21	
322	    22	    static let minShotKey = "FrameJobSwitchSpeakerMinShot"
323	    23	    static let leadKey = "FrameJobSwitchSpeakerLead"
324	    24	    /// "wide" or "hold".
325	    25	    static let crosstalkKey = "FrameJobSwitchSpeakerCrosstalk"
326	    26	    static let bleedKey = "FrameJobSwitchSpeakerBleed"
327	    27	
328	    28	    /// The sheet's opening values: each remembered key clamped into its range, an absent or
329	    29	    /// unreadable key the default. Read through `double(forKey:)`, so a launch argument counts.
330	    30	    static func remembered(_ d: UserDefaults) -> SpeakerSwitch.Settings {
331	    31	        var s = SpeakerSwitch.Settings()
332	    32	        func number(_ key: String, _ range: ClosedRange<Double>, _ fallback: Double) -> Double {
333	    33	            guard d.object(forKey: key) != nil else { return fallback }
334	    34	            let v = d.double(forKey: key)
335	    35	            guard v.isFinite else { return fallback }
336	    36	            return min(max(v, range.lowerBound), range.upperBound)
337	    37	        }
338	    38	        s.minShot = number(minShotKey, minShotRange, s.minShot)
339	    39	        s.lead = number(leadKey, leadRange, s.lead)
340	    40	        s.bleedDB = number(bleedKey, bleedRange, s.bleedDB)
341	    41	        if let raw = d.string(forKey: crosstalkKey), let crosstalk = SpeakerSwitch.Crosstalk(rawValue: raw) {
342	    42	            s.crosstalk = crosstalk
343	    43	        }
344	    44	        return s
345	    45	    }
346	    46	
347	    47	    /// Writes only the remembered keys whose value differs from the sheet's opening values, so a
348	    48	    /// sheet pressed as it opened moves no default (mcp.py's DEFAULTS MOVED guard).
349	    49	    func remember(changedFrom opened: SpeakerSwitch.Settings, in d: UserDefaults) {
350	    50	        if minShot != opened.minShot { d.set(minShot, forKey: Self.minShotKey) }
351	    51	        if lead != opened.lead { d.set(lead, forKey: Self.leadKey) }
352	    52	        if crosstalk != opened.crosstalk { d.set(crosstalk.rawValue, forKey: Self.crosstalkKey) }
353	    53	        if bleedDB != opened.bleedDB { d.set(bleedDB, forKey: Self.bleedKey) }
354	    54	    }
355	    55	}
