357	    57	extension SpeakerSwitch {
358	    58	    /// "N shots: k on <name>, …. Adds M clips." — the angles in the order they first show,
359	    59	    /// each named by `names` (a track id when it has none).
360	    60	    static func summary(_ shots: [Shot], added: Int, names: [UInt32: String]) -> String {
361	    61	        var order: [UInt32] = []
362	    62	        var counts: [UInt32: Int] = [:]
363	    63	        for shot in shots {
364	    64	            if counts[shot.angle] == nil { order.append(shot.angle) }
365	    65	            counts[shot.angle, default: 0] += 1
366	    66	        }
367	    67	        let each = order.map { "\(counts[$0] ?? 0) on \(names[$0] ?? "track \($0)")" }
368	    68	        let count = shots.count == 1 ? "1 shot" : "\(shots.count) shots"
369	    69	        let adds = added == 1 ? "1 clip" : "\(added) clips"
370	    70	        return "\(count): \(each.joined(separator: ", ")). Adds \(adds)."
371	    71	    }
372	    72	
373	    73	    /// The name each of `tracks` is listed by: its own, with " (n)" — n its 1-based position
374	    74	    /// from the back — when two of them share it (SW-13's rule, `SwitchAngle.angles`).
375	    75	    static func titles(_ tracks: [UInt32], in snapshot: ProjectSnapshot) -> [UInt32: String] {
376	    76	        let names = tracks.map { snapshot.track($0)?.name ?? "Track" }
377	    77	        var out: [UInt32: String] = [:]
378	    78	        for (track, name) in zip(tracks, names) {
379	    79	            if names.filter({ $0 == name }).count > 1 {
380	    80	                out[track] = "\(name) (\((snapshot.trackIndex(of: track) ?? 0) + 1))"
381	    81	            } else {
382	    82	                out[track] = name
383	    83	            }
384	    84	        }
385	    85	        return out
386	    86	    }
