392	    92	    {
393	    93	        snapshot.tracks.reversed().map(\.id).filter { track in
394	    94	            selection.contains { clip in
395	    95	                guard clip.track == track, case .media = clip.source, clip.enabled.audio else {
396	    96	                    return false
397	    97	                }
398	    98	                return snapshot.media(for: clip)?.hasAudio == true
399	    99	            }
