567	    19	    /// One microphone's turn: `mic` is its TRACK, `[from, to)` range ticks.
568	    20	    struct Turn: Equatable {
569	    21	        let mic: UInt32
570	    22	        let from: Ticks
571	    23	        let to: Ticks
572	    24	    }
573	    25	
574	    26	    /// The turns of `input`'s read microphones over its range (this file's
575	    27	    /// doc); empty when no run qualifies.
576	    28	    static func turns(_ input: Input) -> [Turn] {
577	    29	        let step = stepTicks
578	    30	        guard step > 0, input.to > input.from else { return [] }
579	    31	        let count = Int((input.to - input.from) / step)
580	    32	        let microphones = input.microphones.filter { $0.level.count == count }
581	    33	        let settings = input.settings
582	    34	        func ticks(_ seconds: Double) -> Ticks {
583	    35	            Ticks((seconds * Double(ReelTime.perSecond)).rounded())
584	    36	        }
585	    37	        let sets = activeSets(microphones, settings: settings)
586	    38	        let steps = labels(microphones, settings: settings)
587	    39	        let order = microphones.map(\.track)
588	    40	
589	    41	        var starts: [(mics: [UInt32], start: Ticks)] = []
590	    42	        for run in bridgedRuns(steps, settings: settings) {
591	    43	            let length = Ticks(run.end - run.start) * step
592	    44	            var mics: [UInt32] = []
593	    45	            switch run.label {
594	    46	            case .nobody: break
595	    47	            case .person(let mic):
596	    48	                if length >= ticks(settings.minTurn) { mics = [mic] }
597	    49	            case .crosstalk:
598	    50	                guard length >= ticks(settings.crosstalkMin) else { break }
