611	    63	                starts.removeLast()
612	    64	                if starts.last?.mics == mics { continue }
613	    65	            }
614	    66	            starts.append((mics, at))
615	    67	        }
616	    68	        guard !starts.isEmpty else { return [] }
617	    69	        starts[0].start = input.from
618	    70	        var out: [Turn] = []
619	    71	        for (index, start) in starts.enumerated() {
620	    72	            let end = index + 1 < starts.count ? min(starts[index + 1].start, input.to) : input.to
