7	     7	
8	     8	    /// The nearest-rank percentile `sorted[⌈p·n⌉ − 1]`; nil for no values.
9	     9	    static func percentile(_ values: [Double], _ p: Double) -> Double? {
10	    10	        guard !values.isEmpty else { return nil }
11	    11	        let sorted = values.sorted()
12	    12	        let rank = Int((p * Double(sorted.count) - 1e-9).rounded(.up))
13	    13	        return sorted[min(sorted.count - 1, max(0, rank - 1))]
14	    14	    }
