18	    18	    /// One label per step. Every microphone's series must be the same length.
19	    19	    static func labels(_ microphones: [Microphone], settings: Settings) -> [Label] {
20	    20	        activeSets(microphones, settings: settings).map { active in
21	    21	            switch active.count {
22	    22	            case 0: return .nobody
23	    23	            case 1: return .person(active[0])
24	    24	            default: return .crosstalk
25	    25	            }
26	    26	        }
27	    27	    }
