29	    29	    /// The microphone tracks active on each step (SW-21), a dominant one alone.
30	    30	    static func activeSets(_ microphones: [Microphone], settings: Settings) -> [[UInt32]] {
31	    31	        let count = microphones.map(\.level.count).min() ?? 0
32	    32	        let threshold = settings.voiceThreshold
33	    33	        // P and F per microphone; a microphone with no speech is never active.
34	    34	        let gauges: [(p: Double, f: Double)?] = microphones.map { mic in
35	    35	            var speech: [Double] = []
36	    36	            var quiet: [Double] = []
37	    37	            for k in 0..<count where mic.covered[k] {
38	    38	                if mic.voice[k] >= threshold { speech.append(mic.level[k]) } else {
39	    39	                    quiet.append(mic.level[k])
40	    40	                }
41	    41	            }
42	    42	            guard let p = percentile(speech, 0.9) else { return nil }
43	    43	            return (p, percentile(quiet, 0.1) ?? -.infinity)
44	    44	        }
45	    45	        var out: [[UInt32]] = []
46	    46	        out.reserveCapacity(count)
47	    47	        for k in 0..<count {
48	    48	            var active: [(track: UInt32, over: Double)] = []
49	    49	            for (index, mic) in microphones.enumerated() {
50	    50	                guard let gauge = gauges[index], mic.covered[k], mic.voice[k] >= threshold
51	    51	                else { continue }
52	    52	                let level = mic.level[k]
53	    53	                guard level >= gauge.p - settings.bleedDB,
54	    54	                    level >= gauge.f + settings.floorMarginDB
55	    55	                else { continue }
56	    56	                active.append((mic.track, level - gauge.p))
57	    57	            }
