59	    59	                active.allSatisfy({ $0.track == top.track
60	    60	                    || top.over - $0.over >= settings.dominanceDB })
61	    61	            {
62	    62	                active = [top]
63	    63	            }
64	    64	            out.append(active.map(\.track))
65	    65	        }
66	    66	        return out
67	    67	    }
