73	    73	    /// Maximal runs of equal labels, in step indices.
74	    74	    static func runs(_ labels: [Label]) -> [Run] {
75	    75	        var out: [Run] = []
76	    76	        for (k, label) in labels.enumerated() {
77	    77	            if var last = out.last, last.label == label {
78	    78	                last.end = k + 1
79	    79	                out[out.count - 1] = last
80	    80	            } else {
81	    81	                out.append(Run(label: label, start: k, end: k + 1))
82	    82	            }
83	    83	        }
84	    84	        return out
85	    85	    }
