87	    87	    /// SW-22 (a), the crosstalk half: each maximal stretch of non-crosstalk runs lying between two
88	    88	    /// crosstalk runs, shorter than `bridge` in total, becomes crosstalk; the runs it joins merge.
89	    89	    static func bridgingCrosstalk(_ runs: [Run], under bridge: Ticks) -> [Run] {
90	    90	        var out: [Run] = []
91	    91	        var index = 0
92	    92	        while index < runs.count {
93	    93	            let run = runs[index]
94	    94	            if run.label != .crosstalk, var last = out.last, last.label == .crosstalk,
95	    95	                let next = runs[index...].firstIndex(where: { $0.label == .crosstalk }),
