120	   120	        let turns = bridgedRuns(labels, settings: settings)
121	   121	
122	   122	        // (c), (d), (e): the starts.
123	   123	        var starts: [(angle: UInt32, start: Ticks)] = []
124	   124	        if let wide { starts.append((wide, from)) }
