126	   126	            let length = Ticks(turn.end - turn.start) * step
127	   127	            let angle: UInt32?
128	   128	            switch turn.label {
129	   129	            case .nobody: angle = nil
130	   130	            case .person(let mic):
131	   131	                angle = length >= ticks(settings.minTurn)
132	   132	                    ? pairing.speakers.first(where: { $0.mic == mic })?.angle : nil
133	   133	            case .crosstalk:
134	   134	                angle = length >= ticks(settings.crosstalkMin) && settings.crosstalk == .wide
135	   135	                    ? wide : nil
136	   136	            }
137	   137	            guard let angle, angle != starts.last?.angle else { continue }
