227	   227	            id.flatMap(track).flatMap { reach($0, from: t) }
228	   228	        }
229	   229	        var out: [Shot] = []
230	   230	        for (index, shot) in shots.enumerated() {
231	   231	            let before = index > 0 ? shots[index - 1].angle : nil
232	   232	            var t = shot.start
233	   233	            while t < shot.end {
234	   234	                if let end = reachOf(shot.angle, t) {
235	   235	                    let stop = min(end, shot.end)
236	   236	                    out.append(Shot(angle: shot.angle, start: t, end: stop))
237	   237	                    t = stop
238	   238	                    continue
239	   239	                }
240	   240	                let back = track(shot.angle)?.clips.map(\.start).filter { $0 > t }.min() ?? shot.end
241	   241	                let uncovered = min(back, shot.end)
242	   242	                while t < uncovered {
243	   243	                    let choice: (UInt32, Ticks)?
244	   244	                    if let w = wide, let end = reachOf(w, t) {
245	   245	                        choice = (w, end)
246	   246	                    } else if let b = before, let end = reachOf(b, t) {
247	   247	                        choice = (b, end)
248	   248	                    } else {
249	   249	                        choice = angles.lazy.compactMap { a in reach(a, from: t).map { (a.track, $0) } }
250	   250	                            .first
251	   251	                    }
252	   252	                    guard let (angle, end) = choice else {
253	   253	                        // No angle covers: SW-24 refuses this; keep the shot's own.
254	   254	                        let next = angles.flatMap(\.clips).map(\.start).filter { $0 > t }.min()
255	   255	                        let stop = min(next ?? uncovered, uncovered)
256	   256	                        out.append(Shot(angle: shot.angle, start: t, end: stop))
257	   257	                        t = stop
258	   258	                        continue
259	   259	                    }
260	   260	                    let stop = min(end, uncovered)
261	   261	                    out.append(Shot(angle: angle, start: t, end: stop))
262	   262	                    t = stop
263	   263	                }
264	   264	            }
265	   265	        }
266	   266	        return coalesced(out)
267	   267	    }
