269	   269	    /// Whether `angle` covers `[start, end)` whole.
270	   270	    static func covers(_ angle: UInt32, _ start: Ticks, _ end: Ticks, in angles: [AngleTrack]) -> Bool {
271	   271	        guard let track = angles.first(where: { $0.track == angle }) else { return false }
272	   272	        guard let reached = reach(track, from: start) else { return false }
273	   273	        return reached >= end
274	   274	    }
