396	    94	    /// Step k's activity: the sample nearest the forward source tick of the step's midpoint,
397	    95	    /// through the covering clip (the later-starting where two cover); nil off every clip or
398	    96	    /// outside the media's 0…duration.
399	    97	    static func faceSeries(_ clips: [FaceClip], from: Ticks, count: Int) -> [Double?] {
400	    98	        let step = stepTicks
401	    99	        return (0..<max(0, count)).map { k -> Double? in
402	   100	            let mid = from + Ticks(k) * step + step / 2
403	   101	            var covering: FaceClip?
404	   102	            for clip in clips where clip.span.start <= mid && mid < clip.span.end {
405	   103	                if covering.map({ clip.span.start >= $0.span.start }) ?? true { covering = clip }
406	   104	            }
407	   105	            guard let clip = covering else { return nil }
408	   106	            let source = clip.times.source(atClip: mid - clip.span.start)
409	   107	            guard source >= 0, source <= clip.duration else { return nil }
410	   108	            let index = clip.grid.index(of: source)
411	   109	            return index < clip.activity.count ? clip.activity[index] : nil
412	   110	        }
413	   111	    }
