453	   151	    /// The media's activity per grid index from the cached samples: each index the marker covers
454	   152	    /// has the opening of its sample, the rest none.
455	   153	    static func storedActivity(_ media: MediaSnapshot, grid: AnalysisGrid, cacheDir: URL)
456	   154	        -> [Double?]
457	   155	    {
458	   156	        var openings = [Double?](repeating: nil, count: grid.count)
459	   157	        if let marker = AnalysisStore.readMarker(.faces, media: media.id, in: cacheDir),
460	   158	            let file = marker.files.first,
461	   159	            let data = AnalysisStore.readPayload(.faces, media: media.id, file: file, in: cacheDir),
462	   160	            let decoded = AnalysisFaces.decode(data), decoded.count == grid.count
463	   161	        {
464	   162	            for range in marker.ranges {
465	   163	                for k in max(0, range.lowerBound)...min(grid.lastIndex, range.upperBound) {
466	   164	                    openings[k] = FaceActivity.opening(decoded.samples[k])
467	   165	                }
468	   166	            }
469	   167	        }
470	   168	        let rate = grid.rate * Double(ReelTime.perSecond)
471	   169	        return FaceActivity.activities(openings, half: FaceActivity.halfWidth(rate: rate))
472	   170	    }
