482	   180	        let windows = faceWindows(
483	   181	            in: document.editedProject, angles: angles, pairing: pairing, from: from, to: to)
484	   182	        let wanted = Set(faceSpeakers(pairing).compactMap(\.angle))
485	   183	        var activity: [UInt32: [Double?]] = [:]
486	   184	        var faces: [FaceAngle] = []
487	   185	        var problems: [String] = []
488	   186	        for angle in angles where wanted.contains(angle.track) {
489	   187	            var clips: [FaceClip] = []
490	   188	            var pending = false
491	   189	            for window in windows where window.track == angle.track {
492	   190	                let missed: Bool
493	   191	                do {
