172	   172	    /// SW-24's list, in its order; empty when nothing is refused.
173	   173	    static func refusals(_ input: Input) -> [String] {
174	   174	        var out: [String] = []
175	   175	        let angles = input.angles.map(\.track)
176	   176	        if angles.count < 2 {
177	   177	            out.append(
178	   178	                "Switch by Speaker needs at least two angles: tracks holding a selected clip "
179	   179	                    + "with a picture.")
180	   180	        }
181	   181	        if angles.count > maxAngles {
182	   182	            out.append(
183	   183	                "Switch by Speaker takes at most nine angles; \(angles.count) tracks hold a "
184	   184	                    + "selected clip with a picture.")
185	   185	        }
186	   186	        let microphones = input.microphones.map(\.track)
187	   187	        let faces = mode(input.pairing) == .faces
188	   188	        // SW-83: in the faces mode a speaker on the wide takes no part.
189	   189	        for speaker in input.pairing.speakers
190	   190	        where !(faces && speaker.angle != nil && speaker.angle == input.pairing.wide) {
191	   191	            guard let mic = speaker.mic, microphones.contains(mic) else {
192	   192	                let track = speaker.angle ?? speaker.mic ?? 0
193	   193	                out.append("The speaker on track \(track) has no microphone.")
194	   194	                continue
195	   195	            }
196	   196	            if speaker.angle.map({ !angles.contains($0) }) ?? true {
197	   197	                out.append("The microphone on track \(mic) has no angle to show its speaker.")
198	   198	            }
199	   199	        }
200	   200	        var counted: [UInt32] = []
201	   201	        for mic in input.pairing.speakers.compactMap(\.mic) where !faces && !counted.contains(mic) {
202	   202	            counted.append(mic)
203	   203	            let n = input.pairing.speakers.filter { $0.mic == mic }.count
204	   204	            if n > 1 {
205	   205	                out.append(
206	   206	                    "Track \(mic) is the microphone for \(n) speakers; each person needs their "
207	   207	                        + "own microphone.")
208	   208	            }
209	   209	        }
210	   210	        out += input.problems
211	   211	        let count = stepTicks > 0 ? Int(max(0, input.to - input.from) / stepTicks) : 0
212	   212	        let a = ReelTime.format(input.from, fps: input.fps, frames: true)
