251	   251	    /// The first stretch of `[from, to)` no angle covers.
252	   252	    static func firstGap(_ angles: [AngleTrack], from: Ticks, to: Ticks)
253	   253	        -> (from: Ticks, to: Ticks)?
254	   254	    {
255	   255	        var t = from
256	   256	        while t < to {
257	   257	            if let end = angles.compactMap({ reach($0, from: t) }).max() {
258	   258	                t = end
259	   259	                continue
260	   260	            }
261	   261	            let next = angles.flatMap(\.clips).map(\.start).filter { $0 > t }.min() ?? to
262	   262	            return (t, min(next, to))
263	   263	        }
264	   264	        return nil
265	   265	    }
