577	    29	        let step = stepTicks
578	    30	        guard step > 0, input.to > input.from else { return [] }
579	    31	        let count = Int((input.to - input.from) / step)
580	    32	        let microphones = input.microphones.filter { $0.level.count == count }
581	    33	        let settings = input.settings
