179	   179	    /// SW-22 (a): a short stretch between two crosstalk runs is crosstalk, then a short nobody
180	   180	    /// between two equal labels takes the label; (b) the runs left are the turns.
181	   181	    static func bridgedRuns(_ labels: [Label], settings: Settings) -> [Run] {
182	   182	        let step = stepTicks
183	   183	        let bridge = Ticks((settings.bridge * Double(ReelTime.perSecond)).rounded())
184	   184	        var turns = bridgingCrosstalk(runs(labels), under: bridge)
185	   185	        var index = 1
186	   186	        while index + 1 < turns.count {
187	   187	            let gap = turns[index]
188	   188	            if gap.label == .nobody, turns[index - 1].label == turns[index + 1].label,
189	   189	                Ticks(gap.end - gap.start) * step < bridge
190	   190	            {
191	   191	                turns[index - 1].end = turns[index + 1].end
192	   192	                turns.removeSubrange(index...(index + 1))
193	   193	            } else {
194	   194	                index += 1
195	   195	            }
196	   196	        }
197	   197	        return turns
198	   198	    }
