200	   200	    /// Starts to shots tiling `[starts[0].start, to)`, empty ones dropped.
201	   201	    static func tile(_ starts: [(angle: UInt32, start: Ticks)], to: Ticks) -> [Shot] {
202	   202	        var out: [Shot] = []
203	   203	        for (index, start) in starts.enumerated() {
204	   204	            let end = index + 1 < starts.count ? min(starts[index + 1].start, to) : to
205	   205	            if end > start.start { out.append(Shot(angle: start.angle, start: start.start, end: end)) }
206	   206	        }
207	   207	        return coalesced(out)
208	   208	    }
209	   209	
210	   210	    static func coalesced(_ shots: [Shot]) -> [Shot] {
211	   211	        var out: [Shot] = []
212	   212	        for shot in shots where shot.end > shot.start {
213	   213	            if let last = out.last, last.angle == shot.angle, last.end == shot.start {
214	   214	                out[out.count - 1] = Shot(angle: last.angle, start: last.start, end: shot.end)
215	   215	            } else {
216	   216	                out.append(shot)
217	   217	            }
218	   218	        }
219	   219	        return out
220	   220	    }
