276	   276	    /// (h): the earliest short shot that can merge does, until none can.
277	   277	    static func merged(_ shots: [Shot], angles: [AngleTrack], minShot: Ticks) -> [Shot] {
278	   278	        var out = coalesced(shots)
279	   279	        while true {
280	   280	            var done = true
281	   281	            for (i, shot) in out.enumerated() where shot.end - shot.start < minShot {
282	   282	                let intoBefore = i > 0 && covers(out[i - 1].angle, shot.start, shot.end, in: angles)
283	   283	                let intoAfter = i + 1 < out.count
284	   284	                    && covers(out[i + 1].angle, shot.start, shot.end, in: angles)
285	   285	                if intoBefore {
286	   286	                    let b = out[i - 1]
287	   287	                    out[i - 1] = Shot(angle: b.angle, start: b.start, end: shot.end)
288	   288	                } else if intoAfter {
289	   289	                    let a = out[i + 1]
290	   290	                    out[i + 1] = Shot(angle: a.angle, start: shot.start, end: a.end)
291	   291	                } else {
292	   292	                    continue
293	   293	                }
294	   294	                out.remove(at: i)
295	   295	                out = coalesced(out)
296	   296	                done = false
297	   297	                break
298	   298	            }
299	   299	            if done { return out }
300	   300	        }
301	   301	    }
