386	    84	    /// An angle clip as the faces series reads it: its span, its times, its media's sample grid
387	    85	    /// and duration, and the media's activity per grid index.
388	    86	    struct FaceClip {
389	    87	        let span: Span
390	    88	        let times: AnalysisClipTimes
