428	   126	    static func faceWindows(
429	   127	        in project: ReelProject, angles: [AngleTrack], pairing: Pairing, from: Ticks, to: Ticks
430	   128	    ) -> [FaceWindow] {
431	   129	        let snapshot = project.snapshot
432	   130	        let wanted = Set(faceSpeakers(pairing).compactMap(\.angle))
433	   131	        let half = Ticks((FaceActivity.window / 2 * Double(ReelTime.perSecond)).rounded())
434	   132	        var out: [FaceWindow] = []
435	   133	        for angle in angles where wanted.contains(angle.track) {
436	   134	            for span in angle.clips where span.end > from && span.start < to {
437	   135	                guard let clip = snapshot.clip(span.clip), let media = snapshot.media(for: clip),
438	   136	                    media.kind == .video, media.hasVideo
439	   137	                else { continue }
440	   138	                let times = AnalysisClipTimes(clip: clip, media: media, map: project.sourceMap(clip.id))
441	   139	                let a = times.source(atClip: max(span.start, from) - span.start)
442	   140	                let b = times.source(atClip: min(span.end, to) - span.start)
443	   141	                let low = max(0, min(a, b) - half)
444	   142	                let high = min(media.duration, max(a, b) + half)
445	   143	                guard high > low else { continue }
446	   144	                out.append(FaceWindow(
447	   145	                    track: angle.track, span: span, media: media, times: times, window: low...high))
448	   146	            }
449	   147	        }
450	   148	        return out
451	   149	    }
